public sealed record FinanceFredOptions
{
    public const string Section="Finance:Fred";
    public bool Enabled { get; set; }
    public string ApiKey { get; set; }="";
    public string BaseUrl { get; set; }="https://api.stlouisfed.org";
    public int TimeoutSeconds { get; set; }=30;
    public int MaximumVintageObservations { get; set; }=5000;
    public string QuarantineDirectory { get; set; }=Path.Combine(Path.GetTempPath(),"bigbrain-finance","macro-quarantine");
    internal bool ApiKeyConfigured=>!string.IsNullOrWhiteSpace(ApiKey);
    internal void Validate(){if(!Uri.TryCreate(BaseUrl,UriKind.Absolute,out var uri)||uri.Scheme!=Uri.UriSchemeHttps||!string.Equals(uri.Host,"api.stlouisfed.org",StringComparison.OrdinalIgnoreCase)||TimeoutSeconds is <5 or >120||MaximumVintageObservations is <1 or >10000)throw new InvalidOperationException("FRED configuration is invalid or not first-party bounded.");}
}

