        catch(Exception ex) when(ex is InvalidDataException or FormatException or JsonException or InvalidOperationException){RecordEuropeanCandidate(candidateId,provider,sourceUrl,rightsUrl,path,hash,acquired,seriesId,"LOCAL_RESEARCH","FAIL","REJECTED",null);throw;}
