    private static string[] Csv(string line){var cells=new List<string>();var value=new StringBuilder();var quoted=false;for(var i=0;i<line.Length;i++){var ch=line[i];if(ch=='\"'){if(quoted&&i+1<line.Length&&line[i+1]=='\"'){value.Append('\"');i++;}else quoted=!quoted;}else if(ch==','&&!quoted){cells.Add(value.ToString());value.Clear();}else value.Append(ch);}if(quoted)throw new InvalidDataException("Unterminated ECB CSV quote.");cells.Add(value.ToString());return cells.ToArray();}
